+export const requireSessionOrBearerAuth = createMiddleware<{
+  Bindings: Env
+  Variables: Variables
+}>(async (c, next) => {
+  c.set("authTimestamp", Date.now())
+
+  const sessionAuth = await resolveSessionAuth(c, false)
+  if (sessionAuth instanceof Response) {
+    return sessionAuth
+  }
+  if (sessionAuth) {
+    c.set("userId", sessionAuth.userId)
+    await next()
+    return
+  }
+
+  const bearerAuth = await resolveBearerAuth(c, true)
+  if (bearerAuth instanceof Response) {
+    return bearerAuth
+  }
+
+  c.set("userId", bearerAuth.userId)
+  c.set("tokenScope", bearerAuth.tokenScope)
+  await next()
+})
+
+async function resolveSessionAuth(
+  c: Context<{ Bindings: Env; Variables: Variables }>,
+  strict: boolean,
+): Promise<{ userId: string } | Response | null> {
+  const sessionToken = getCookie(c, "session")
+  if (!sessionToken) {
+    return strict ? c.json({ error: "Not authenticated" }, 401) : null
+  }
+
+  const session = await getSession(c.env.ENTIRE_CACHE, sessionToken)
+  if (!session) {
+    return strict ? c.json({ error: "Session expired" }, 401) : null
+  }
+
+  const csrfError = await validateSessionCsrf(c, session.userId)
+  if (csrfError) {
+    return csrfError
+  }
+
+  return { userId: session.userId }
+}
+
+async function validateSessionCsrf(
+  c: Context<{ Bindings: Env; Variables: Variables }>,
+  userId: string,
+): Promise<Response | null> {
+  const method = c.req.method
+  if (method !== "POST" && method !== "PUT" && method !== "DELETE" && method !== "PATCH") {
+    return null
+  }
+
+  const csrfCookie = getCookie(c, "csrf")
+  const csrfHeader = c.req.header("X-CSRF-Token")
+
+  let csrfFailureReason: string | null = null
+  if (!csrfCookie && !csrfHeader) {
+    csrfFailureReason = "missing_both"
+  } else if (!csrfCookie) {
+    csrfFailureReason = "missing_cookie"
+  } else if (!csrfHeader) {
+    csrfFailureReason = "missing_header"
+  } else if (!(await timingSafeEqual(csrfCookie, csrfHeader))) {
+    csrfFailureReason = "mismatch"
+  }
+
+  if (!csrfFailureReason) {
+    return null
+  }
+
+  console.log(
+    `[csrf] validation_failed`,
+    JSON.stringify({
+      reason: csrfFailureReason,
+      method,
+      path: c.req.path,
+      userId,
+    }),
+  )
+  return c.json({ error: "CSRF token invalid" }, 403)
+}
+
+async function resolveBearerAuth(
+  c: Context<{ Bindings: Env; Variables: Variables }>,
+  strict: boolean,
+): Promise<{ userId: string; tokenScope: string | null } | Response | null> {
+  const authHeader = c.req.header("Authorization")
+  if (!authHeader) {
+    return strict ? c.json({ error: "Not authenticated" }, 401) : null
+  }
+
+  const parts = authHeader.split(" ")
+  if (parts.length !== 2 || parts[0] !== "Bearer") {
+    return strict ? c.json({ error: "Not authenticated" }, 401) : null
+  }
+
+  const token = parts[1]
+  if (!token.startsWith(API_TOKEN_PREFIX)) {
+    return strict ? c.json({ error: "Not authenticated" }, 401) : null
+  }
+
+  const hash = await sha256Hex(token)
+  const db = getDb(c.env)
+  const lookup = await db.apiTokens.findByTokenHash(hash)
+  if (!lookup) {
+    return strict ? c.json({ error: "Not authenticated" }, 401) : null
+  }
+
+  if (new Date(lookup.expires_at) < new Date()) {
+    return strict ? c.json({ error: "Token expired" }, 401) : null
+  }
+
+  try {
+    c.executionCtx.waitUntil(db.apiTokens.updateLastUsedAt(lookup.id))
+  } catch {
+    void db.apiTokens.updateLastUsedAt(lookup.id)
+  }
+
+  return { userId: lookup.user_id, tokenScope: lookup.scope ?? null }
+}
